package com.bplus.share;
import android.content.*;import android.net.nsd.*;import android.net.wifi.WifiManager;import android.os.*;import java.net.*;import java.util.*;
/** Screen-scoped NSD. Local network changes and receiver readiness are checked without remote polling. */
public final class NearbyDiscovery{
 public interface View{void address(String ip);void state(int message);}
 private final Context c;private final View view;private final Handler h=new Handler(Looper.getMainLooper());private NsdManager nsd;private NsdManager.RegistrationListener reg;private NsdManager.DiscoveryListener scan;private WifiManager.MulticastLock lock;private boolean live,resolving,scanRunning;private final Map<String,NsdServiceInfo> seen=new LinkedHashMap<>();private final Map<String,String> addresses=new HashMap<>();private final Set<String> loaded=new HashSet<>(),profilePending=new HashSet<>();private long opened;private int generation,readyTries;private int resolveTicket;private String network="",last="";private final ArrayDeque<NsdServiceInfo> queue=new ArrayDeque<>();private final Set<String> queued=new HashSet<>();private final Map<String,Integer> tries=new HashMap<>();private final ArrayDeque<String> log=new ArrayDeque<>();
 public NearbyDiscovery(Context c,View v){this.c=c;view=v;}
 public void start(){opened=SystemClock.elapsedRealtime();live=true;network=snapshot();note("Nearby opened");restart();h.postDelayed(watch,3000);}
 public void stop(){live=false;generation++;h.removeCallbacksAndMessages(null);close();note("Nearby closed");}
 public void refresh(){maintain(true);}
 public void maintain(boolean manual){if(!live)return;note(manual?"Manual refresh":"Automatic maintenance");if(scan==null||!scanRunning){if(reg==null){restart();return;}startScan(generation);return;}for(Map.Entry<String,NsdServiceInfo> e:new ArrayList<>(seen.entrySet())){String ip=addresses.get(e.getKey());if(ip!=null){if(manual||!loaded.contains(ip))offerProfile(ip);}else if(!queued.contains(e.getKey())){tries.remove(e.getKey());enqueue(e.getValue(),generation);}}}
 public void diagnostic(String text){h.post(()->{if(live)note(text);});}
 private void offerProfile(String ip){if(!profilePending.add(ip))return;note("Profile queued "+ip);view.address(ip);}
 public String details(){return "B+ Offline Share "+AppVersion.display(c)+" / Android API "+android.os.Build.VERSION.SDK_INT+"\nLAN="+network+"\nSelected IPv4="+Net.localIp(c)+"\nReceiver="+TransferService.ready()+"\nService=_bplusshare._tcp. TCP47200\n"+android.text.TextUtils.join("\n",log);}
 private void note(String text){last=text;log.addLast(new java.text.SimpleDateFormat("HH:mm:ss.SSS",java.util.Locale.US).format(new Date())+" +"+(SystemClock.elapsedRealtime()-opened)+"ms "+text);while(log.size()>100)log.removeFirst();}
 private final Runnable watch=new Runnable(){public void run(){if(!live)return;String current=snapshot();if(!current.equals(network)){network=current;note("Network interfaces changed");restart();}else if(reg!=null&&!TransferService.ready()){note("Receiver lost readiness");restart();}h.postDelayed(this,3000);}};
 private void restart(){generation++;close();readyTries=0;waitReceiver(generation);}
 private void waitReceiver(int gen){if(!live||gen!=generation)return;if(Net.localIp(c)==null||!LocalNetwork.usable(c)){view.state(R.string.no_lan);note("No supported LAN IPv4");return;}try{if(!TransferService.ready())TransferService.start(c);}catch(Exception e){note("Receiver start "+e.getClass().getSimpleName());}if(!TransferService.ready()){view.state(R.string.nearby_wait_receiver);if(++readyTries<20)h.postDelayed(()->waitReceiver(gen),500);else{note("Receiver TCP47200 not ready");view.state(R.string.nearby_receiver_failed);}return;}register(gen);}
 private void register(int gen){if(!live||gen!=generation)return;try{nsd=(NsdManager)c.getSystemService(Context.NSD_SERVICE);lock=((WifiManager)c.getApplicationContext().getSystemService(Context.WIFI_SERVICE)).createMulticastLock("bplus-nearby");lock.setReferenceCounted(false);lock.acquire();reg=new NsdManager.RegistrationListener(){public void onServiceRegistered(NsdServiceInfo i){h.post(()->{if(valid(gen)){note("Registered "+i.getServiceName());view.state(R.string.nearby_notice);}});}public void onRegistrationFailed(NsdServiceInfo i,int e){h.post(()->{if(valid(gen)){note("Registration failed "+e);view.state(R.string.nearby_failed);}});}public void onServiceUnregistered(NsdServiceInfo i){}public void onUnregistrationFailed(NsdServiceInfo i,int e){}};NsdServiceInfo ad=new NsdServiceInfo();ad.setServiceName("Bplus-"+Store.get("deviceId",""));ad.setServiceType("_bplusshare._tcp.");ad.setPort(Store.PORT);nsd.registerService(ad,NsdManager.PROTOCOL_DNS_SD,reg);startScan(gen);
 }catch(Exception e){note("NSD setup "+e.getClass().getSimpleName());view.state(R.string.nearby_failed);}}
 private void startScan(int gen){if(!valid(gen)||scan!=null)return;try{
 scan=new NsdManager.DiscoveryListener(){public void onDiscoveryStarted(String t){h.post(()->{if(valid(gen)){scanRunning=true;note("Scan started");}});}public void onDiscoveryStopped(String t){h.post(()->{if(valid(gen)){scan=null;scanRunning=false;note("Scan stopped");}});}public void onStartDiscoveryFailed(String t,int e){h.post(()->{if(valid(gen)){scan=null;scanRunning=false;note("Scan failed "+e);view.state(R.string.nearby_failed);}});}public void onStopDiscoveryFailed(String t,int e){}public void onServiceLost(NsdServiceInfo i){h.post(()->{if(valid(gen)){String name=i.getServiceName();note("Service lost "+name);seen.remove(name);String ip=addresses.remove(name);if(ip!=null)loaded.remove(ip);queued.remove(name);}});}public void onServiceFound(NsdServiceInfo i){h.post(()->enqueue(i,gen));}};nsd.discoverServices("_bplusshare._tcp.",NsdManager.PROTOCOL_DNS_SD,scan);h.postDelayed(()->{if(valid(gen)&&queued.isEmpty()){view.state(R.string.nearby_empty);note("No matching service yet");}},12000);
 }catch(Exception e){scan=null;scanRunning=false;note("NSD scan setup "+e.getClass().getSimpleName());view.state(R.string.nearby_failed);}}
 private boolean valid(int gen){return live&&gen==generation;}
 private void enqueue(NsdServiceInfo i,int gen){String name=i.getServiceName();if(!valid(gen)||!name.startsWith("Bplus-")||name.startsWith("Bplus-"+Store.get("deviceId","")))return;if(!seen.containsKey(name)){if(seen.size()>=64){note("Service capacity reached");return;}note("Found "+name);seen.put(name,i);}if(queued.contains(name)||queue.size()>=64)return;queued.add(name);queue.add(i);resolve(gen);}
 private void resolve(int gen){if(!valid(gen)||resolving||queue.isEmpty())return;NsdServiceInfo i=queue.remove();resolving=true;note("Resolve started "+i.getServiceName()+" queue="+queue.size());final int ticket=++resolveTicket;h.postDelayed(()->{if(valid(gen)&&resolving&&ticket==resolveTicket){resolveTicket++;failure(i,-2,gen);}},6000);try{nsd.resolveService(i,new NsdManager.ResolveListener(){public void onResolveFailed(NsdServiceInfo ignored,int error){h.post(()->{if(ticket==resolveTicket)failure(i,error,gen);});}public void onServiceResolved(NsdServiceInfo result){h.post(()->{if(!valid(gen)||ticket!=resolveTicket)return;resolveTicket++;resolving=false;InetAddress a=result.getHost();if(a instanceof Inet4Address){note("Resolved "+result.getServiceName()+" "+a.getHostAddress());addresses.put(i.getServiceName(),a.getHostAddress());offerProfile(a.getHostAddress());}else{note("Resolved without IPv4");queued.remove(i.getServiceName());}resolve(gen);});}});}catch(Exception e){failure(i,-1,gen);}}
 private void failure(NsdServiceInfo i,int error,int gen){if(!valid(gen))return;resolving=false;String name=i.getServiceName();int n=tries.containsKey(name)?tries.get(name)+1:1;tries.put(name,n);note("Resolve failed "+error+" attempt"+n);if(n<3)h.postDelayed(()->{if(valid(gen)){queue.add(i);resolve(gen);}},700L*n);else{queued.remove(name);view.state(R.string.nearby_resolve_failed);}resolve(gen);}
 public void profileResult(String ip,boolean ok){h.post(()->{if(live){profilePending.remove(ip);if(ok)loaded.add(ip);else loaded.remove(ip);note("Profile "+ip+" "+(ok?"loaded":"failed"));}});}
 private void close(){if(nsd!=null){try{if(scan!=null)nsd.stopServiceDiscovery(scan);}catch(Exception ignored){}try{if(reg!=null)nsd.unregisterService(reg);}catch(Exception ignored){}}try{if(lock!=null&&lock.isHeld())lock.release();}catch(Exception ignored){}scan=null;scanRunning=false;reg=null;lock=null;seen.clear();addresses.clear();loaded.clear();profilePending.clear();resolving=false;resolveTicket++;queue.clear();queued.clear();tries.clear();}
 private String snapshot(){ArrayList<String> ips=new ArrayList<>();try{Enumeration<NetworkInterface> all=NetworkInterface.getNetworkInterfaces();while(all.hasMoreElements()){NetworkInterface i=all.nextElement();if(!i.isUp()||i.isLoopback())continue;Enumeration<InetAddress> addresses=i.getInetAddresses();while(addresses.hasMoreElements()){InetAddress a=addresses.nextElement();if(a instanceof Inet4Address&&!a.isLoopbackAddress()&&!a.isLinkLocalAddress())ips.add(i.getName()+"="+a.getHostAddress());}}}catch(Exception e){ips.add("unavailable");}Collections.sort(ips);return android.text.TextUtils.join(", ",ips);}
}
